import React, { useState } from 'react';
import { Map, MapPin, ChevronRight, ChevronLeft, Search, Box, Database, Globe, activity } from 'lucide-react';

const AreasZonesTab = () => {
  const [viewLevel, setViewLevel] = useState('ZONES'); // ZONES -> AREAS -> BINS
  const [selectedZone, setSelectedZone] = useState(null);
  const [selectedArea, setSelectedArea] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  // --- THE FULL DIRECTORY DATA ---
  const zoneData = [
    {
      id: 'Z-101', name: 'NORTH_SECTOR', code: 'NS-ALPHA', status: 'ACTIVE',
      areas: [
        { id: 'A-101', name: 'Hillside Drive', location: 'Sector 4, North Ridge', code: 'HSD-44', bins: ['BN-401', 'BN-405', 'BN-409'] },
        { id: 'A-102', name: 'University Road', location: 'Campus East Gate', code: 'URD-12', bins: ['BN-502', 'BN-503', 'BN-508'] },
        { id: 'A-103', name: 'Green Park', location: 'Central North', code: 'GPK-09', bins: ['BN-601', 'BN-602'] }
      ]
    },
    {
      id: 'Z-202', name: 'CENTRAL_HUB', code: 'CH-BRAVO', status: 'HEAVY_LOAD',
      areas: [
        { id: 'A-201', name: 'Main Square', location: 'Downtown Center', code: 'MSQ-01', bins: ['BN-101', 'BN-102', 'BN-103', 'BN-104'] },
        { id: 'A-202', name: 'Shopping Plaza', location: 'Midtown Mall', code: 'SPZ-09', bins: ['BN-201', 'BN-205'] }
      ]
    },
    {
      id: 'Z-303', name: 'INDUSTRIAL_VALLEY', code: 'IV-CHARLIE', status: 'OPTIMAL',
      areas: [
        { id: 'A-301', name: 'Factory Lane', location: 'Industrial Gate 1', code: 'FLN-88', bins: ['BN-901', 'BN-905'] },
        { id: 'A-302', name: 'Warehouse Row', location: 'South Loading Dock', code: 'WHR-22', bins: ['BN-881', 'BN-882'] }
      ]
    }
  ];

  // --- SEARCH FILTER ---
  const displayData = viewLevel === 'ZONES' 
    ? zoneData.filter(z => z.name.includes(searchQuery.toUpperCase()))
    : selectedZone?.areas.filter(a => a.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="w-full animate-slot flex flex-col gap-6">

      {/* --- HEADER SECTION --- */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b-8 border-[#47510B] pb-6">
        <div className="flex items-center gap-4">
          {viewLevel !== 'ZONES' && (
            <button 
              onClick={() => setViewLevel(viewLevel === 'BINS' ? 'AREAS' : 'ZONES')}
              className="bg-[#AB1717] text-white p-2 border-4 border-[#47510B] hover:bg-[#47510B] transition-colors"
            >
              <ChevronLeft size={24} strokeWidth={3} />
            </button>
          )}
          <div>
            <h2 className="text-4xl font-[1000] italic text-[#47510B] uppercase tracking-tighter leading-none">
              {viewLevel === 'ZONES' ? 'ZONE_MASTER_LIST' : selectedZone.name}
            </h2>
            <p className="text-xs font-black text-[#AB1717] uppercase tracking-[0.3em] mt-1">
              {viewLevel === 'ZONES' ? 'System_Physical_Hierarchy' : `Scanning_Sector: ${selectedZone.code}`}
            </p>
          </div>
        </div>

        <div className="relative w-full md:w-72">
          <Search className="absolute left-3 top-2.5 text-[#47510B] opacity-50" size={18} />
          <input 
            type="text" 
            placeholder="SEARCH_DIRECTORY..."
            className="w-full bg-white border-[4px] border-[#47510B] py-2 pl-10 pr-4 text-[11px] font-black uppercase focus:bg-[#CAD23C]/20 outline-none"
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* --- VIEW LEVEL 1: ALL ZONES --- */}
      {viewLevel === 'ZONES' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {displayData.map(zone => (
            <div 
              key={zone.id} 
              onClick={() => {setSelectedZone(zone); setViewLevel('AREAS');}}
              className="bg-white border-[6px] border-[#47510B] p-6 cursor-pointer hover:bg-[#CAD23C] hover:-translate-y-2 transition-all shadow-[10px_10px_0_0_#47510B] group"
            >
              <div className="flex justify-between items-start mb-6">
                <Globe className="text-[#AB1717] group-hover:rotate-90 transition-transform duration-500" size={32} />
                <span className="text-[10px] font-black bg-[#47510B] text-[#FDFAD8] px-2 py-1 italic uppercase">{zone.code}</span>
              </div>
              <h3 className="text-2xl font-[1000] text-[#47510B] uppercase italic mb-1">{zone.name}</h3>
              <div className="w-full h-1 bg-[#47510B]/10 mb-4" />
              <div className="flex justify-between items-end">
                <div>
                  <p className="text-[9px] font-black opacity-40 uppercase">Sub_Areas</p>
                  <p className="text-xl font-black text-[#47510B]">{zone.areas.length}</p>
                </div>
                <div className="bg-[#AB1717] text-white p-1 border-2 border-[#47510B]">
                   <ChevronRight size={20} strokeWidth={3} />
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* --- VIEW LEVEL 2: AREAS WITHIN SELECTED ZONE --- */}
      {viewLevel === 'AREAS' && (
        <div className="flex flex-col gap-4">
          {displayData.map(area => (
            <div 
              key={area.id} 
              onClick={() => {setSelectedArea(area); setViewLevel('BINS');}}
              className="bg-[#A1AED1]/10 border-[4px] border-[#47510B] hover:bg-white flex flex-col md:flex-row items-stretch cursor-pointer transition-all shadow-[6px_6px_0_0_#47510B]"
            >
              <div className="bg-[#47510B] text-[#CAD23C] p-6 flex flex-col justify-center items-center min-w-[120px] border-r-[4px] border-[#47510B]">
                <span className="text-[9px] font-black uppercase opacity-60 mb-1">Area_Code</span>
                <span className="text-lg font-black italic">{area.code}</span>
              </div>
              <div className="p-6 flex-grow">
                <h3 className="text-2xl font-black text-[#47510B] uppercase italic">{area.name}</h3>
                <div className="flex items-center gap-2 mt-2">
                  <MapPin size={14} className="text-[#AB1717]" />
                  <span className="text-xs font-bold text-[#47510B]/60 uppercase italic tracking-widest">{area.location}</span>
                </div>
              </div>
              <div className="bg-[#CAD23C] p-6 flex items-center justify-between md:justify-end gap-8 border-t-[4px] md:border-t-0 md:border-l-[4px] border-[#47510B]">
                <div className="text-right">
                  <p className="text-[9px] font-black uppercase opacity-60">Node_Count</p>
                  <p className="text-xl font-black text-[#47510B]">{area.bins.length} UNITS</p>
                </div>
                <ChevronRight size={28} strokeWidth={3} className="text-[#47510B]" />
              </div>
            </div>
          ))}
        </div>
      )}

      {/* --- VIEW LEVEL 3: BINS WITHIN SELECTED AREA --- */}
      {viewLevel === 'BINS' && (
        <div className="bg-white border-[8px] border-[#47510B] p-8 shadow-[15px_15px_0_0_#A1AED1]">
          <div className="flex justify-between items-center border-b-4 border-[#47510B]/10 pb-6 mb-8">
            <div className="flex items-center gap-4">
               <div className="bg-[#AB1717] p-3 border-4 border-[#47510B]">
                  <Box className="text-white" size={30} />
               </div>
               <div>
                  <h3 className="text-3xl font-[1000] text-[#47510B] uppercase italic">{selectedArea.name}</h3>
                  <p className="text-xs font-black text-[#AB1717] uppercase tracking-[0.2em]">Active_Telemetry_Nodes</p>
               </div>
            </div>
            <div className="hidden sm:block text-right">
                <span className="text-[10px] font-black uppercase opacity-40">System_Uplink</span>
                <p className="text-sm font-black text-[#47510B]">ENCRYPTED_ID_LIST</p>
            </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-4">
            {selectedArea.bins.map(binId => (
              <div key={binId} className="border-[4px] border-[#47510B] p-5 flex flex-col items-center gap-3 bg-[#FDFAD8] hover:bg-[#CAD23C] transition-all group">
                <Database size={24} className="text-[#AB1717] group-hover:scale-110 transition-transform" />
                <span className="text-sm font-[1000] text-[#47510B] font-mono tracking-tighter">{binId}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default AreasZonesTab;
